const key = p => new URL(p + '?v=' + FILES[p], self.registration.scope).href;

async function store(cache, p) {
  const r = await fetch(new URL(p, self.registration.scope), { cache: 'reload' });
  if (!r.ok) throw new Error(p + ' ' + r.status);
  await cache.put(key(p), r);
}

async function missing(cache) {
  const have = new Set((await cache.keys()).map(r => r.url));
  return Object.keys(FILES).filter(p => !have.has(key(p)));
}

async function broadcast(msg) {
  for (const c of await self.clients.matchAll()) c.postMessage(msg);
}

// Fill in the rest of the guide in the background, a few files at a time.
let filling = null;
function fill() {
  return filling ||= (async () => {
    const cache = await caches.open(CACHE);
    const todo = await missing(cache), total = Object.keys(FILES).length;
    let done = total - todo.length;
    await broadcast({ type: 'progress', done, total });
    const queue = todo.slice();
    await Promise.all(Array.from({ length: 4 }, async () => {
      while (queue.length) {
        const p = queue.shift();
        try { await store(cache, p); done++; } catch (e) {}
        await broadcast({ type: 'progress', done, total });
      }
    }));
  })().finally(() => { filling = null; });
}

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const have = new Set((await cache.keys()).map(r => r.url));
    await Promise.all(CORE.filter(p => !have.has(key(p))).map(p => store(cache, p)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const keep = new Set(Object.keys(FILES).map(key));
    for (const r of await cache.keys()) if (!keep.has(r.url)) await cache.delete(r);
    await self.clients.claim();
    fill();
  })());
});

self.addEventListener('message', e => {
  if (e.data === 'status') e.waitUntil(fill());
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const scope = new URL(self.registration.scope);
  if (url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  let p = decodeURIComponent(url.pathname.slice(scope.pathname.length));
  if (req.mode === 'navigate' || p === '') p = 'index.html';
  if (!(p in FILES)) return;
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(key(p));
    if (hit) return hit;
    const r = await fetch(req);
    if (r.ok && req.mode !== 'navigate') cache.put(key(p), r.clone());
    return r;
  })());
});
